<?php require_once __DIR__ . '/includes/config.php';role(['admin','hr','payroll']);$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){check();if(!empty($_FILES['csv']['tmp_name'])){$f=fopen($_FILES['csv']['tmp_name'],'r');fgetcsv($f);$type=$_POST['type'];$n=0;if($type==='employees'){$s=db()->prepare('INSERT INTO employees(employee_no,full_name,national_id,department,job_title,employment_status,appointment_date,bank_account) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE full_name=VALUES(full_name),department=VALUES(department),employment_status=VALUES(employment_status)');while($r=fgetcsv($f)){if(!$r||!$r[0])continue;$r=array_pad($r,8,'');$s->execute(array_slice($r,0,8));$n++;}}else{$s=db()->prepare('SELECT id FROM employees WHERE employee_no=?');$i=db()->prepare('INSERT INTO payroll(employee_id,employee_no,pay_period,gross_amount,payment_reference,payment_date) VALUES(?,?,?,?,?,?)');while($r=fgetcsv($f)){if(!$r||!$r[0])continue;$r=array_pad($r,5,'');$s->execute([$r[0]]);$id=$s->fetchColumn();$i->execute([$id?:null,$r[0],$r[1],$r[2],$r[3],$r[4]?:null]);$n++;}}fclose($f);$msg="Imported $n records";log_action('CSV_IMPORT',$msg);}}head('CSV import');?><h1>Import CSV</h1><div class="panel"><p>Save Excel sheets as CSV before importing. First row must contain headings.</p><p><?=e($msg)?></p><form method="post" enctype="multipart/form-data"><input type="hidden" name="token" value="<?=e(token())?>"><label>Import type<select name="type"><option value="employees">Employees</option><option value="payroll">Payroll</option></select></label><label>CSV file<input type="file" name="csv" accept=".csv" required></label><button>Import file</button></form><h3>Employee columns</h3><code>employee_no,full_name,national_id,department,job_title,employment_status,appointment_date,bank_account</code><h3>Payroll columns</h3><code>employee_no,pay_period,gross_amount,payment_reference,payment_date</code></div><?php foot();?>